#!/bin/bash
set -e

lightx2v_path=/data/LightX2V
model_path=/data/models/Hunyuan3D-2.1

export PLATFORM=cuda DEVICE_TYPE=cuda
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0}"
export INFER_PROFILE_LEVEL=2

source "${lightx2v_path}/scripts/base/base.sh"

# base.sh sets BF16; Hunyuan3D uses FP16.
export DTYPE=FP16

# Use the mesh generated by the Shape case.
python "${lightx2v_path}/tools/postprocess/postprocess_paint.py" \
  --hy_repo /data/Hunyuan3D-2.1 \
  --model_path "${model_path}" \
  --mesh_path "${lightx2v_path}/save_results/hunyuan3d-2.1-shape_1card.glb" \
  --image_path /data/inputs/hunyuan3d/demo.png \
  --save_path "${lightx2v_path}/save_results/hunyuan3d-2.1-paint_1card.glb" \
  --device cuda \
  --dino_ckpt_path /data/models/dinov2-giant \
  --realesrgan_ckpt_path /data/models/Hunyuan3D-2.1/RealESRGAN_x4plus.pth \
  --render_size 2048 \
  --texture_size 4096 \
  --max_num_view 6 \
  --resolution 512 \
  "$@"
